INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '印刷業', '2024年における印刷業の従業者一人あたりの現金給与額は、およそいくらか。最も近いものを選びなさい。', '[{"headers": ["年次", "事業所数", "従業者数（人）", "現金給与総額（百万円）", "付加価値額（百万円）"], "rows": [["2022", "3,200", "32,500", "124,000", "200,000"], ["2023", "3,050", "30,200", "121,000", "190,000"], ["2024", "2,890", "28,400", "118,500", "182,000"]]}]', '["4.17万円", "41.7万円", "239,662円", "4,172,535円", "いずれでもない"]', 3, '["現金給与総額を従業者数で割って求める。2024年の現金給与総額は118,500（百万円）＝118,500,000,000円、従業者数は28,400人である。\n118,500,000,000÷28,400＝およそ4,172,535円となる。よって選択肢Dが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
