INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '医療機器製造業', '2024年における医療機器製造業の従業者一人あたりの付加価値額は、およそいくらか。最も近いものを選びなさい。', '[{"headers": ["年次", "事業所数", "従業者数（人）", "現金給与総額（百万円）", "付加価値額（百万円）"], "rows": [["2022", "420", "10,800", "98,500", "118,600"], ["2023", "410", "10,300", "95,200", "123,500"], ["2024", "395", "9,800", "91,800", "128,900"]]}]', '["1.32万円", "13.2万円", "76,028円", "13,153,061円", "いずれでもない"]', 3, '["付加価値額を従業者数で割って求める。2024年の付加価値額は128,900（百万円）＝128,900,000,000円、従業者数は9,800人である。\n128,900,000,000÷9,800＝およそ13,153,061円となる。よって選択肢Dが正解。\n\n---\n\n## 意識調査表（問7〜問12）"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '在宅勤務の生産性実感（国別）', '日本とフランスにおいて、「とても向上した」または「やや向上した」と回答した人の合計割合を比較したとき、フランスは日本より何ポイント高いか。最も近いものを選びなさい。', '[{"headers": ["", "とても向上した", "やや向上した", "変わらない", "やや低下した", "とても低下した"], "rows": [["日本", "14.0%", "26.5%", "32.0%", "17.5%", "10.0%"], ["フランス", "22.0%", "31.0%", "28.0%", "12.0%", "7.0%"]]}]', '["9.5pt", "11.0pt", "12.5pt", "14.0pt", "15.5pt"]', 2, '["日本の合計は14.0＋26.5＝40.5（％）。フランスの合計は22.0＋31.0＝53.0（％）。\n差は53.0－40.5＝12.5（ポイント）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '電子書籍の利用頻度（年代別）', '20代と60代において、「よく利用する」または「ときどき利用する」と回答した人の合計割合を比較したとき、その差はいくらか。最も近いものを選びなさい。', '[{"headers": ["", "よく利用する", "ときどき利用する", "あまり利用しない", "全く利用しない"], "rows": [["20代", "35.0%", "30.0%", "20.0%", "15.0%"], ["60代", "8.0%", "17.0%", "30.0%", "45.0%"]]}]', '["32.0%", "36.0%", "40.0%", "44.0%", "48.0%"]', 2, '["20代の合計は35.0＋30.0＝65.0（％）。60代の合計は8.0＋17.0＝25.0（％）。\n差は65.0－25.0＝40.0（％）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '食料品の値上げへの不安度（国別）', '日本と韓国において、「非常に不安」または「やや不安」と回答した人の合計割合を比較したとき、韓国は日本より何ポイント高いか。最も近いものを選びなさい。', '[{"headers": ["", "非常に不安", "やや不安", "あまり不安でない", "全く不安でない"], "rows": [["日本", "38.0%", "40.5%", "15.0%", "6.5%"], ["韓国", "41.0%", "40.0%", "12.0%", "7.0%"]]}]', '["1.0pt", "1.5pt", "2.0pt", "2.5pt", "3.0pt"]', 3, '["日本の合計は38.0＋40.5＝78.5（％）。韓国の合計は41.0＋40.0＝81.0（％）。\n差は81.0－78.5＝2.5（ポイント）となる。よって選択肢Dが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '祝日の過ごし方に関する満足度（世代別）', '30代と70代において、「とても満足」または「やや満足」と回答した人の合計割合を比較したとき、70代は30代より何ポイント高いか。最も近いものを選びなさい。', '[{"headers": ["", "とても満足", "やや満足", "あまり満足でない", "全く満足でない"], "rows": [["30代", "24.0%", "38.0%", "26.0%", "12.0%"], ["70代", "35.0%", "40.0%", "18.0%", "7.0%"]]}]', '["9.0pt", "11.0pt", "13.0pt", "15.0pt", "17.0pt"]', 2, '["30代の合計は24.0＋38.0＝62.0（％）。70代の合計は35.0＋40.0＝75.0（％）。\n差は75.0－62.0＝13.0（ポイント）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '異常気象への危機感（国別）', '日本とオーストラリアにおいて、「非常に感じる」または「やや感じる」と回答した人の合計割合を比較したとき、その差はいくらか。最も近いものを選びなさい。', '[{"headers": ["", "非常に感じる", "やや感じる", "あまり感じない", "全く感じない"], "rows": [["日本", "30.0%", "42.0%", "20.0%", "8.0%"], ["オーストラリア", "48.0%", "35.0%", "12.0%", "5.0%"]]}]', '["7.0pt", "9.0pt", "11.0pt", "13.0pt", "15.0pt"]', 2, '["日本の合計は30.0＋42.0＝72.0（％）。オーストラリアの合計は48.0＋35.0＝83.0（％）。\n差は83.0－72.0＝11.0（ポイント）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '苦情対応への満足度（業界別）', '通信業と小売業において、「とても満足」または「やや満足」と回答した人の合計割合を比較したとき、小売業は通信業より何ポイント高いか。最も近いものを選びなさい。', '[{"headers": ["", "とても満足", "やや満足", "あまり満足でない", "全く満足でない"], "rows": [["通信業", "20.0%", "32.0%", "28.0%", "20.0%"], ["小売業", "32.0%", "34.5%", "20.5%", "13.0%"]]}]', '["10.5pt", "12.5pt", "14.5pt", "16.5pt", "18.5pt"]', 2, '["通信業の合計は20.0＋32.0＝52.0（％）。小売業の合計は32.0＋34.5＝66.5（％）。\n差は66.5－52.0＝14.5（ポイント）となる。よって選択肢Cが正解。\n\n---\n\n## 構成比の推移表（問13〜問20）"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '国内旅行者の交通手段別割合の推移', '2024年の全体の旅行者数をNとおくとき、航空機とその他を合わせた旅行者数を表す式として正しいものを選びなさい。', '[{"headers": ["", "自家用車", "鉄道", "バス", "航空機", "その他"], "rows": [["2010年", "45%", "30%", "15%", "7%", "3%"], ["2018年", "40%", "33%", "14%", "10%", "3%"], ["2024年", "35%", "35%", "10%", "15%", "5%"]]}]', '["N/10", "N/8", "N/5", "3N/10", "2N/5"]', 2, '["2024年の航空機は15％、その他は5％なので、合計は15＋5＝20（％）。\n全体をNとすると、20／100＝1／5であるから、求める式はN/5となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9005);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '国内旅行者の交通手段別割合の推移', '2010年のバス利用者数をBとおくとき、2010年における全体の旅行者数を表す式として正しいものを選びなさい。', '[{"headers": ["", "自家用車", "鉄道", "バス", "航空機", "その他"], "rows": [["2010年", "45%", "30%", "15%", "7%", "3%"], ["2018年", "40%", "33%", "14%", "10%", "3%"], ["2024年", "35%", "35%", "10%", "15%", "5%"]]}]', '["5B", "15B/2", "20B/3", "25B/3", "10B"]', 2, '["2010年のバスの割合は15％である。全体をWとすると、W：B＝100：15という比の関係が成り立つ。\nこれを解くと15W＝100Bとなり、W＝100B/15＝20B/3と導かれる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9005);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '農業産出額の品目別構成比の推移', '2023年の全体の農業産出額をPとおくとき、畜産とその他を合わせた産出額を表す式として正しいものを選びなさい。', '[{"headers": ["", "米", "野菜", "果実", "畜産", "その他"], "rows": [["1995年", "35%", "25%", "12%", "23%", "5%"], ["2010年", "28%", "27%", "14%", "25%", "6%"], ["2023年", "20%", "26%", "13%", "33%", "8%"]]}]', '["2P/5", "41P/100", "9P/20", "23P/50", "P/2"]', 1, '["2023年の畜産は33％、その他は8％なので、合計は33＋8＝41（％）。\n全体をPとすると、求める式は41P/100となる。よって選択肢Bが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9006);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '農業産出額の品目別構成比の推移', '1995年の果実の産出額をFとおくとき、1995年における全体の産出額を表す式として正しいものを選びなさい。', '[{"headers": ["", "米", "野菜", "果実", "畜産", "その他"], "rows": [["1995年", "35%", "25%", "12%", "23%", "5%"], ["2010年", "28%", "27%", "14%", "25%", "6%"], ["2023年", "20%", "26%", "13%", "33%", "8%"]]}]', '["6F", "25F/3", "9F", "28F/3", "32F/3"]', 1, '["1995年の果実の割合は12％である。全体をWとすると、W：F＝100：12という比の関係が成り立つ。\nこれを解くと12W＝100Fとなり、W＝100F/12＝25F/3と導かれる。よって選択肢Bが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9006);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', 'スマートフォン所有者の利用アプリカテゴリー別割合の推移', '2025年の全体の利用者数をUとおくとき、動画とその他を合わせた利用者数を表す式として正しいものを選びなさい。', '[{"headers": ["", "SNS", "動画", "ゲーム", "ニュース", "その他"], "rows": [["2015年", "25%", "20%", "30%", "15%", "10%"], ["2020年", "30%", "25%", "22%", "13%", "10%"], ["2025年", "35%", "28%", "15%", "12%", "10%"]]}]', '["9U/25", "19U/50", "2U/5", "21U/50", "11U/25"]', 1, '["2025年の動画は28％、その他は10％なので、合計は28＋10＝38（％）。\n全体をUとすると、38／100＝19／50であるから、求める式は19U/50となる。よって選択肢Bが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9007);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', 'スマートフォン所有者の利用アプリカテゴリー別割合の推移', '2015年のゲームの利用者数をGとおくとき、2015年における全体の利用者数を表す式として正しいものを選びなさい。', '[{"headers": ["", "SNS", "動画", "ゲーム", "ニュース", "その他"], "rows": [["2015年", "25%", "20%", "30%", "15%", "10%"], ["2020年", "30%", "25%", "22%", "13%", "10%"], ["2025年", "35%", "28%", "15%", "12%", "10%"]]}]', '["5G/2", "3G", "10G/3", "7G/2", "4G"]', 2, '["2015年のゲームの割合は30％である。全体をWとすると、W：G＝100：30という比の関係が成り立つ。\nこれを解くと30W＝100Gとなり、W＝100G/30＝10G/3と導かれる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9007);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '廃棄物処理方法別割合の推移', '2024年の全体の廃棄物量をWとおくとき、リサイクルとその他を合わせた廃棄物量を表す式として正しいものを選びなさい。', '[{"headers": ["", "焼却", "埋立", "リサイクル", "その他"], "rows": [["2000年", "60%", "25%", "10%", "5%"], ["2012年", "48%", "25%", "20%", "7%"], ["2024年", "38%", "15%", "40%", "7%"]]}]', '["9W/20", "47W/100", "12W/25", "49W/100", "W/2"]', 1, '["2024年のリサイクルは40％、その他は7％なので、合計は40＋7＝47（％）。\n全体をWとすると、求める式は47W/100となる。よって選択肢Bが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9008);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '廃棄物処理方法別割合の推移', '2000年の埋立量をLとおくとき、2000年における全体の廃棄物量を表す式として正しいものを選びなさい。', '[{"headers": ["", "焼却", "埋立", "リサイクル", "その他"], "rows": [["2000年", "60%", "25%", "10%", "5%"], ["2012年", "48%", "25%", "20%", "7%"], ["2024年", "38%", "15%", "40%", "7%"]]}]', '["3L", "7L/2", "4L", "9L/2", "5L"]', 2, '["2000年の埋立の割合は25％である。全体をWとすると、W：L＝100：25という比の関係が成り立つ。\nこれを解くと25W＝100Lとなり、W＝4Lと導かれる。よって選択肢Cが正解。\n\n---\n\n## 店舗別売上表（問21〜問28）"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9008);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '店舗別売上（4月〜6月）', '4つの店舗のうち、4月から6月にかけての売上の増加率が最も大きい店舗を一つ選びなさい。', '[{"headers": ["店舗名", "4月売上", "5月売上", "6月売上", "3カ月合計", "平均売上"], "rows": [["G店", "1,100", "1,150", "1,250", "3,500", "1,166.7"], ["H店", "2,000", "1,950", "2,100", "6,050", "2,016.7"], ["I店", "600", "900", "1,080", "2,580", "860.0"], ["J店", "1,500", "1,600", "1,750", "4,850", "1,616.7"]]}]', '["G店", "H店", "I店", "J店", "すべて同じ"]', 2, '["各店舗の増加率を計算する。G店は1,250/1,100＝約1.14倍、H店は2,100/2,000＝1.05倍、I店は1,080/600＝1.80倍、J店は1,750/1,500＝約1.17倍である。\nI店は4月時点の売上が小さいため、増加率で見ると他の店舗を大きく上回る。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9009);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '店舗別売上（4月〜6月）', '4月から6月までの3カ月間における1カ月あたりの平均売上が、4月の売上に対して1.15倍を超えている店舗はいくつあるか。', '[{"headers": ["店舗名", "4月売上", "5月売上", "6月売上", "3カ月合計", "平均売上"], "rows": [["G店", "1,100", "1,150", "1,250", "3,500", "1,166.7"], ["H店", "2,000", "1,950", "2,100", "6,050", "2,016.7"], ["I店", "600", "900", "1,080", "2,580", "860.0"], ["J店", "1,500", "1,600", "1,750", "4,850", "1,616.7"]]}]', '["なし", "1つ", "2つ", "3つ", "4つ"]', 1, '["各店舗について「4月売上×1.15」と平均売上を比較する。\nG店：1,100×1.15＝1,265に対し平均は1,166.7で下回る。H店：2,000×1.15＝2,300に対し平均は2,016.7で下回る。\nI店：600×1.15＝690に対し平均は860.0で大きく上回る。J店：1,500×1.15＝1,725に対し平均は1,616.7で下回る。\n条件を満たすのはI店のみで1つ。よって選択肢Bが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9009);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '店舗別売上（4月〜6月）', '4つの店舗のうち、4月から6月にかけての売上の増加率が最も大きい店舗を一つ選びなさい。', '[{"headers": ["店舗名", "4月売上", "5月売上", "6月売上", "3カ月合計", "平均売上"], "rows": [["ア店", "800", "850", "900", "2,550", "850.0"], ["イ店", "1,200", "1,300", "1,450", "3,950", "1,316.7"], ["ウ店", "400", "700", "900", "2,000", "666.7"], ["エ店", "2,500", "2,450", "2,600", "7,550", "2,516.7"]]}]', '["ア店", "イ店", "ウ店", "エ店", "すべて同じ"]', 2, '["各店舗の増加率を計算する。ア店は900/800＝1.125倍、イ店は1,450/1,200＝約1.21倍、ウ店は900/400＝2.25倍、エ店は2,600/2,500＝1.04倍である。\nウ店は4月時点の売上が特に小さいため、増加率が突出して大きくなる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9010);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '店舗別売上（4月〜6月）', '4月から6月までの3カ月間における1カ月あたりの平均売上が、4月の売上に対して1.20倍を超えている店舗はいくつあるか。', '[{"headers": ["店舗名", "4月売上", "5月売上", "6月売上", "3カ月合計", "平均売上"], "rows": [["ア店", "800", "850", "900", "2,550", "850.0"], ["イ店", "1,200", "1,300", "1,450", "3,950", "1,316.7"], ["ウ店", "400", "700", "900", "2,000", "666.7"], ["エ店", "2,500", "2,450", "2,600", "7,550", "2,516.7"]]}]', '["なし", "1つ", "2つ", "3つ", "4つ"]', 1, '["各店舗について「4月売上×1.20」と平均売上を比較する。\nア店：800×1.20＝960に対し平均は850.0で下回る。イ店：1,200×1.20＝1,440に対し平均は1,316.7で下回る。\nウ店：400×1.20＝480に対し平均は666.7で大きく上回る。エ店：2,500×1.20＝3,000に対し平均は2,516.7で下回る。\n条件を満たすのはウ店のみで1つ。よって選択肢Bが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9010);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '店舗別売上（4月〜6月）', '5つの店舗のうち、4月から6月にかけての売上の増加率が最も大きい店舗を一つ選びなさい。', '[{"headers": ["店舗名", "4月売上", "5月売上", "6月売上", "3カ月合計", "平均売上"], "rows": [["カ店", "1,000", "1,050", "1,100", "3,150", "1,050.0"], ["キ店", "700", "850", "1,000", "2,550", "850.0"], ["ク店", "1,800", "1,750", "1,900", "5,450", "1,816.7"], ["ケ店", "300", "500", "650", "1,450", "483.3"], ["コ店", "1,200", "1,260", "1,350", "3,810", "1,270.0"]]}]', '["カ店", "キ店", "ク店", "ケ店", "コ店"]', 3, '["各店舗の増加率を計算する。カ店は1.10倍、キ店は約1.43倍、ク店は約1.06倍、ケ店は650/300＝約2.17倍、コ店は1,350/1,200＝1.125倍である。\nケ店は4月時点の売上が特に小さいため、増加率が突出して大きくなる。よって選択肢Dが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9011);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '店舗別売上（4月〜6月）', '4月から6月までの3カ月間における1カ月あたりの平均売上が、4月の売上に対して1.10倍を超えている店舗はいくつあるか。', '[{"headers": ["店舗名", "4月売上", "5月売上", "6月売上", "3カ月合計", "平均売上"], "rows": [["カ店", "1,000", "1,050", "1,100", "3,150", "1,050.0"], ["キ店", "700", "850", "1,000", "2,550", "850.0"], ["ク店", "1,800", "1,750", "1,900", "5,450", "1,816.7"], ["ケ店", "300", "500", "650", "1,450", "483.3"], ["コ店", "1,200", "1,260", "1,350", "3,810", "1,270.0"]]}]', '["なし", "1つ", "2つ", "3つ", "4つ"]', 2, '["各店舗について「4月売上×1.10」と平均売上を比較する。\nカ店：1,000×1.10＝1,100に対し平均は1,050.0で下回る。キ店：700×1.10＝770に対し平均は850.0で上回る。\nク店：1,800×1.10＝1,980に対し平均は1,816.7で下回る。ケ店：300×1.10＝330に対し平均は483.3で上回る。コ店：1,200×1.10＝1,320に対し平均は1,270.0で下回る。\n条件を満たすのはキ店とケ店の2つ。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9011);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '店舗別売上（4月〜6月）', '4つの店舗のうち、4月から6月にかけての売上の増加率が最も大きい店舗を一つ選びなさい。', '[{"headers": ["店舗名", "4月売上", "5月売上", "6月売上", "3カ月合計", "平均売上"], "rows": [["サ店", "500", "520", "560", "1,580", "526.7"], ["シ店", "900", "1,000", "1,150", "3,050", "1,016.7"], ["ス店", "250", "400", "520", "1,170", "390.0"], ["セ店", "1,600", "1,550", "1,650", "4,800", "1,600.0"]]}]', '["サ店", "シ店", "ス店", "セ店", "すべて同じ"]', 2, '["各店舗の増加率を計算する。サ店は560/500＝1.12倍、シ店は1,150/900＝約1.28倍、ス店は520/250＝2.08倍、セ店は1,650/1,600＝約1.03倍である。\nス店は4月時点の売上が特に小さいため、増加率が突出して大きくなる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9012);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '店舗別売上（4月〜6月）', '4月から6月までの3カ月間における1カ月あたりの平均売上が、4月の売上に対して1.25倍を超えている店舗はいくつあるか。', '[{"headers": ["店舗名", "4月売上", "5月売上", "6月売上", "3カ月合計", "平均売上"], "rows": [["サ店", "500", "520", "560", "1,580", "526.7"], ["シ店", "900", "1,000", "1,150", "3,050", "1,016.7"], ["ス店", "250", "400", "520", "1,170", "390.0"], ["セ店", "1,600", "1,550", "1,650", "4,800", "1,600.0"]]}]', '["なし", "1つ", "2つ", "3つ", "4つ"]', 1, '["各店舗について「4月売上×1.25」と平均売上を比較する。\nサ店：500×1.25＝625に対し平均は526.7で下回る。シ店：900×1.25＝1,125に対し平均は1,016.7で下回る。\nス店：250×1.25＝312.5に対し平均は390.0で上回る。セ店：1,600×1.25＝2,000に対し平均は1,600.0で下回る。\n条件を満たすのはス店のみで1つ。よって選択肢Bが正解。\n\n---\n\n## 増加率算出表（問29〜問34）"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', 9012);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '自動車生産台数（千台）', '2024年における商用車の生産台数は、2022年と比較して約何%増加したか。最も近いものを選びなさい。', '[{"headers": ["年", "乗用車", "商用車", "その他"], "rows": [["2022年", "3,200", "850", "150"], ["2023年", "3,350", "900", "160"], ["2024年", "3,520", "970", "180"]]}]', '["10.2%", "12.1%", "14.1%", "16.5%", "18.8%"]', 2, '["2022年の商用車は850千台、2024年は970千台である。増加率は（970－850）÷850＝120÷850＝約0.141となり、百分率に直すと約14.1％となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '図書館貸出冊数（冊）', '2024年における専門書の貸出冊数は、2022年と比較して約何%増加したか。最も近いものを選びなさい。', '[{"headers": ["年", "小説", "専門書", "児童書"], "rows": [["2022年", "45,000", "18,000", "32,000"], ["2023年", "47,500", "19,200", "33,800"], ["2024年", "51,200", "21,500", "35,100"]]}]', '["15.6%", "17.5%", "19.4%", "21.6%", "23.8%"]', 2, '["2022年の専門書は18,000冊、2024年は21,500冊である。増加率は（21,500－18,000）÷18,000＝3,500÷18,000＝約0.194となり、百分率に直すと約19.4％となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '訪日外国人数（千人）', '2024年におけるアジアからの訪日外国人数は、2022年と比較して約何%増加したか。最も近いものを選びなさい。', '[{"headers": ["年", "アジア", "欧米", "その他"], "rows": [["2022年", "2,800", "650", "220"], ["2023年", "3,400", "780", "260"], ["2024年", "4,200", "920", "310"]]}]', '["40.0%", "45.0%", "50.0%", "55.0%", "60.0%"]', 2, '["2022年のアジアは2,800千人、2024年は4,200千人である。増加率は（4,200－2,800）÷2,800＝1,400÷2,800＝0.50となり、百分率に直すと50.0％となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '太陽光発電設備容量（MW）', '2024年における産業用の設備容量は、2022年と比較して約何%増加したか。最も近いものを選びなさい。', '[{"headers": ["年", "住宅用", "産業用", "公共用"], "rows": [["2022年", "1,200", "3,400", "600"], ["2023年", "1,350", "3,800", "650"], ["2024年", "1,520", "4,350", "710"]]}]', '["22.5%", "25.3%", "27.9%", "30.6%", "33.2%"]', 2, '["2022年の産業用は3,400MW、2024年は4,350MWである。増加率は（4,350－3,400）÷3,400＝950÷3,400＝約0.279となり、百分率に直すと約27.9％となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', 'オンライン講座受講者数（人）', '2024年におけるIT講座の受講者数は、2022年と比較して約何%増加したか。最も近いものを選びなさい。', '[{"headers": ["年", "語学", "IT", "ビジネス"], "rows": [["2022年", "8,500", "6,200", "4,100"], ["2023年", "9,800", "7,900", "4,500"], ["2024年", "11,200", "9,800", "4,950"]]}]', '["48.5%", "53.2%", "58.1%", "63.0%", "67.8%"]', 2, '["2022年のITは6,200人、2024年は9,800人である。増加率は（9,800－6,200）÷6,200＝3,600÷6,200＝約0.581となり、百分率に直すと約58.1％となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '病院の外来患者数（人/月）', '2024年における外科の外来患者数は、2022年と比較して約何%増加したか。最も近いものを選びなさい。', '[{"headers": ["年", "内科", "外科", "小児科"], "rows": [["2022年", "12,000", "4,800", "3,200"], ["2023年", "12,500", "5,100", "3,050"], ["2024年", "13,100", "5,600", "2,900"]]}]', '["12.5%", "14.6%", "16.7%", "18.8%", "20.9%"]', 2, '["2022年の外科は4,800人、2024年は5,600人である。増加率は（5,600－4,800）÷4,800＝800÷4,800＝約0.167となり、百分率に直すと約16.7％となる。よって選択肢Cが正解。\n\n---\n\n## 総合問題（問35〜問40）"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '業務別平均処理件数と人数', '3業務を合わせた全担当者の平均処理件数はいくらか。最も近いものを選びなさい。', '[{"headers": ["業務", "平均処理件数（件/日）", "人数（人）"], "rows": [["受付", "25", "12"], ["審査", "40", "18"], ["発送", "15", "10"]]}]', '["26.7件", "27.9件", "29.25件", "30.5件", "31.8件"]', 2, '["単純に3つの平均処理件数を足して3で割るのではなく、業務ごとの人数で重みづけした加重平均を求める必要がある。\n（25×12＋40×18＋15×10）÷（12＋18＋10）＝（300＋720＋150）÷40＝1,170÷40＝29.25（件）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '会員種別構成比', '全会員数をNとおくとき、スタンダード会員とプレミアム会員を合わせた人数を表す式として正しいものを選びなさい。', '[{"headers": ["会員種別", "構成比"], "rows": [["フリー会員", "30%"], ["スタンダード会員", "45%"], ["プレミアム会員", "25%"]]}]', '["N/2", "3N/5", "13N/20", "7N/10", "3N/4"]', 3, '["スタンダード会員（45％）とプレミアム会員（25％）を合わせると70％となる。全会員数をNとすると、70／100＝7／10であるから、求める式は7N/10となる。よって選択肢Dが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '支店別年間売上（万円）', 'R支店とS支店の2021年から2023年までの3年間の売上合計を比較したとき、R支店の合計はS支店の合計のおよそ何倍か。最も近いものを選びなさい。', '[{"headers": ["", "2021年", "2022年", "2023年", "3年合計"], "rows": [["R支店", "2,200", "2,400", "2,600", "7,200"], ["S支店", "1,500", "1,650", "1,800", "4,950"]]}]', '["1.30倍", "1.36倍", "1.42倍", "1.45倍", "1.52倍"]', 3, '["R支店の3年合計は7,200万円、S支店の3年合計は4,950万円である。\n7,200÷4,950＝約1.45となる。よって選択肢Dが最も近い。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '学年別平均点と人数', '3学年を合わせた全生徒の平均点はいくらか。最も近いものを選びなさい。', '[{"headers": ["学年", "平均点", "人数（人）"], "rows": [["1年", "68", "120"], ["2年", "74", "110"], ["3年", "81", "95"]]}]', '["70.5点", "72.1点", "73.8点", "75.4点", "77.0点"]', 2, '["学年ごとの人数で重みづけした加重平均を求める。\n（68×120＋74×110＋81×95）÷（120＋110＋95）＝（8,160＋8,140＋7,695）÷325＝23,995÷325＝約73.83（点）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '家計調査の支出割合', '総支出額をHとおくとき、教育費と医療費を合わせた支出額を表す式として正しいものを選びなさい。', '[{"headers": ["支出項目", "割合"], "rows": [["教育費", "20%"], ["娯楽費", "15%"], ["医療費", "10%"], ["その他", "55%"]]}]', '["H/5", "3H/10", "2H/5", "9H/20", "H/2"]', 1, '["教育費（20％）と医療費（10％）を合わせると30％となる。総支出額をHとすると、30／100＝3／10であるから、求める式は3H/10となる。よって選択肢Bが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '店舗別年間来客数（千人）', 'V店とW店の2021年から2023年までの3年間の来客数合計を比較したとき、V店の合計はW店の合計のおよそ何倍か。最も近いものを選びなさい。', '[{"headers": ["", "2021年", "2022年", "2023年", "3年合計"], "rows": [["V店", "3,000", "3,200", "3,400", "9,600"], ["W店", "2,000", "2,150", "2,300", "6,450"]]}]', '["1.35倍", "1.42倍", "1.49倍", "1.55倍", "1.62倍"]', 2, '["V店の3年合計は9,600千人、W店の3年合計は6,450千人である。\n9,600÷6,450＝約1.49となる。よって選択肢Cが最も近い。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り）', NULL);
